            {
              "option": "Keep registry purely behavioral and omit visual/layout metadata",
              "rejected_because": "Leaves an architectural blind spot where shared UX structure and visual intent are undocumented and hard to port or validate."
            },
            {
              "option": "Store raw CSS/design-token/framework style props directly in the registry",
              "rejected_because": "Violates platform abstraction and would couple the registry to specific implementations rather than semantic intent."
            }
          ]
        },
        "consequences": {
          "expected": [
            "UI registry entries can better express cross-platform UX intent and composition rules.",
            "Migration and reconstruction tasks can preserve layout and visual hierarchy more accurately.",
            "Some existing UI elements will need incremental enrichment to adopt the expanded metadata model."
          ],
          "risks": [
            "Visual metadata may drift toward implementation detail if not governed carefully.",
            "Different contributors may interpret abstract styling categories inconsistently until conventions stabilize."
          ]
        },
        "guard_rails": [
          "Do NOT store raw CSS, Tailwind classes, or framework-specific style props as authoritative UI registry metadata.",
          "Do NOT replace semantic purpose/data-contract metadata with purely visual descriptions; visual metadata is additive.",
          "When registering or updating UI elements, prefer abstract layout and visual intent terms such as card grid, dense inspector, primary action emphasis, or embedded shell chrome over pixel-level specifications."
