            "system://datastores",
            "query_resource",
            "datastore-bootstrap"
          ]
        },
        "decision": {
          "chosen": "Adopt a two-part policy for lazy-created JSON-backed resources: (1) bootstrap creates known backing files in an empty canonical state where appropriate, such as datastores.json initialized to []; and (2) resource-query tooling treats ENOENT for known registered JSON-backed resources as an empty resource instead of surfacing an internal error. Unknown resource URIs must still return INVALID_URI.",
          "alternatives": [
            {
              "option": "Surface ENOENT to clients for missing backing files",
