            "extensions/vscode/src/context-builder.ts",
            "extensions/vscode/src/extension.ts"
          ]
        },
        "decision": {
          "chosen": "Implement role-specific prompts as \"Architect Lenses.\" Surface the active lens via a subtle badge in the response header (e.g. \"Architect Lens: Performance / Refactor / Reliability / Security\"). Show the badge ONLY when the lens materially changes reasoning — different evidence pulled, different query protocol, different ADR set. Stay silent for trivial tasks. Lens selection driven by the same intent detector that drives _createContextPlan().",
          "alternatives": [
            {
              "option": "Always announce role in prose",
              "rejected_because": "Becomes gimmicky and erodes user trust over time."
            },
            {
              "option": "Never expose role to user",
              "rejected_because": "Loses explainability and debuggability — users can't tell why an answer leans one way or another."
            },
            {
              "option": "User-selected lens dropdown",
              "rejected_because": "Adds UI burden for what should be inferred from intent in 95% of cases."
