      {
        "id": "ADR-197",
        "title": "Provider-safe plugin tool names and native-source discovery",
        "date": "2026-05-17T03:15:34.813Z",
        "decided_by": "collaborative",
        "status": "accepted",
        "context": {
          "problem": "Dotted plugin tool names such as examples.hello-events.greet can pass DreamGraph plugin gates but are rejected by LLM providers that require tool names to match ^[a-zA-Z0-9_-]+$. Separately, bootstrap/scan can no-op on C/C++ projects because native source extensions are absent from scanner extension allow-lists.",
          "constraints": [
            "Provider-facing tool names must match ^[a-zA-Z0-9_-]+$ and therefore cannot contain dots.",
            "Plugin contribution gates must reject invalid tool names before tools enter MCP/provider catalogs.",
            "The rule must be applied consistently in daemon manager, host gates, SDK manifest validation, and examples/tests.",
            "Scanner discovery must include common C/C++ source/header extensions without weakening existing language support."
          ],
          "affected_entities": [
            "src/plugins/manager.ts",
            "packages/host/src/gates.ts",
            "packages/sdk/src/manifest.ts",
            "src/tools/scan-project.ts",
            "src/tools/init-graph.ts"
          ],
          "related_tensions": [
            "Plugin IDs often use reverse-DNS/dotted naming while provider tool identifiers forbid dots.",
            "Backward compatibility with old <plugin-id>.<tool> names conflicts with provider-safe registration.",
            "Language-specific scan allow-lists can silently exclude valid target projects."
          ]
