            {
              "option": "Promote winning futures directly into hard enforcement or accepted truth without review",
              "rejected_because": "ADR-204 forbids turning AFE into a hard enforcement mechanism without separate governance."
            },
            {
              "option": "Store only a free-text note about future recommendations",
              "rejected_because": "That would make provenance, decision status, and supersession semantics too ambiguous for operational use."
            }
          ]
        },
        "consequences": {
          "expected": [
