            "data_scan_state_v1",
            "data_store",
            "graph_snapshot",
            "cognitive_graph_rag",
            "graph_enrichment"
          ]
        },
        "decision": {
          "chosen": "Supersede ADR-236's reader-compatibility exception with a durable instance-level consistency policy: preview and staging remain outside the critical section; authoritative reconciliation acquires one exclusive graph barrier, revalidates the expected revision, journals prior and next bodies, replaces canonical stores, publishes scan_state.json last, invalidates caches, and releases only after success or complete rollback. Canonical multi-store readers hold the shared side for their entire snapshot. Ordinary enrichment, dream, scheduler, Architect/MCP, and manual atomic graph mutations use the exclusive side and cannot cross reconciliation.",
          "alternatives": [
            {
              "option": "Immutable per-revision snapshot directories plus active pointer",
              "rejected_because": "It would require a broader migration of all path consumers and persistence writers than Slice 4 needs; the centralized barrier proves the invariant without changing JSON locations."
            },
            {
              "option": "ADR-236 journal-only commit with scan_state publication last",
              "rejected_because": "Rollback repairs disk but cannot retract a mixed snapshot already observed by an unbarriered reader."
            },
            {
              "option": "Ad-hoc scan locks at individual reader and mutation call sites",
              "rejected_because": "Coverage would be fragile and legacy readers could bypass the contract; the common cache, snapshot, atomic-write, and reconciliation boundaries are narrower and coherent."
            }
          ]
        },
        "consequences": {
          "expected": [
            "Readers begun before commit finish on the prior complete revision",
            "Readers arriving during commit wait and then see the new complete revision or restored prior revision",
            "Canonical atomic mutations serialize against reconciliation",
            "Interrupted journals roll back during recovery; rollback failure remains explicitly recovery_required",
            "scan_state.json is the final publication write and caches are invalidated before readers resume"
          ],
          "risks": [
            "Long multi-store reads can delay reconciliation and long commits can briefly delay reads",
            "Direct legacy filesystem readers outside canonical graph APIs require explicit audit/migration before they may claim multi-store consistency",
            "The barrier is daemon-process scoped; multiple independent daemon processes for one instance remain prohibited by the existing single-daemon ownership contract"
          ]
