        "id": "ADR-238",
        "title": "Revision-scoped bridge discovery cache and bounded asynchronous audit evidence",
        "date": "2026-08-21T20:09:32.665Z",
        "decided_by": "collaborative",
        "status": "accepted",
        "context": {
          "problem": "The external/Codex stdio-to-HTTP bridge duplicates tools/list during cold startup and synchronously appends complete tool results on the request hot path, producing measurable cold-path amplification and making large governed results vulnerable to audit backpressure.",
          "constraints": [
            "Daemon MCP remains the sole repository and tool authority",
            "Capabilities must not cross sessions or instances",
            "MCP stdout must remain protocol-pure",
            "Audit must retain correlation, ordering, failures, size and integrity evidence",
            "Reconnect must invalidate cached discovery",
            "ADR-050 keeps transport normalization silent; diagnostics belong at bridge operation boundaries"
          ],
          "affected_entities": [
            "mcp_tool_invocation_flow",
            "mcp_tool_session_orchestrator",
            "codex-cli-native-adapter",
            "standalone-architect-cli-bridge"
          ]
        },
        "decision": {
          "chosen": "Connect and initialize the upstream once, defer tools/list until the downstream client requests it, cache the result only for the lifetime of that upstream session, and invalidate it on upstream close. Move bridge audit writes to an ordered bounded buffer; store full small records but replace oversized input/result bodies with bounded previews plus byte size and SHA-256 hash. Flush within a bounded shutdown budget and surface overflow/write failure on stderr.",
          "alternatives": [
            {
              "option": "Keep the eager startup probe and add a longer health timeout",
              "rejected_because": "It preserves duplicate discovery and conceals rather than removes cold-path work."
            },
            {
              "option": "Persist a cross-session tool-list cache",
              "rejected_because": "It risks stale capabilities and instance/session leakage without a daemon revision invalidation contract."
            },
            {
              "option": "Drop or sample audit records",
              "rejected_because": "It weakens governed provenance and can silently omit security-relevant failures."
            }
          ]
        },
        "consequences": {
          "expected": [
            "Cold startup performs one initialize and at most one downstream-demanded discovery sequence",
            "Warm tools/list calls avoid upstream round trips within one bridge session",
            "Ordinary tool latency no longer waits for filesystem audit persistence",
            "Large audit evidence has bounded memory/disk amplification while retaining integrity and provenance"
          ],
          "risks": [
            "A server that mutates tools mid-session without reconnect will not be observed until cache invalidation",
            "Buffered records may be lost if the process is forcibly terminated before bounded flush",
            "Overflow handling must remain observable and preferentially preserve failures"
          ]
        },
        "guard_rails": [
          "Do NOT reuse discovery results across upstream sessions or instances.",
          "Do NOT write operational diagnostics to MCP stdout.",
          "Do NOT silently drop failed-call audit evidence.",
          "Do NOT omit correlation id, duration, original byte size, and integrity hash when bounding audit bodies.",
          "Do NOT automatically replay mutations after reconnect."
        ],
        "tags": [
          "mcp",
