        "context": {
          "problem": "Stacked connect, discovery, queue, tool, idle, wall, and user-cancellation budgets could terminate one operation without identifying the owning layer or preserving correlation and retryability.",
          "constraints": [
            "Daemon/MCP remains repository authority",
