            "mcp_tool_session_orchestrator",
            "codex-cli-native-adapter",
            "standalone-architect-cli-bridge"
          ]
        },
        "decision": {
          "chosen": "Represent every deadline or cancellation as one typed outcome naming exactly one owner (connect, discovery, queue, tool, idle, wall, or user), propagate AbortSignal upstream, separate stage budgets, and make only explicitly transient layers retryable.",
          "alternatives": [
