            "extensions/vscode/src/autonomy.ts",
            "extensions/vscode/src/autonomy-loop.ts",
            "ArchitectRunResult",
            "codex-cli",
            "copilot-cli",
            "native-api-tool-loop"
          ],
          "related_tensions": [
            "adapter-normalization-vs-core-contamination",
            "checkpoint-completion-vs-requested-target-completion"
          ]
        },
        "decision": {
          "chosen": "Continuation-envelope semantics belong to the native API adapter/controller boundary and are not part of the CLI adapter contract. Controllers may project continuation-derived intent into neutral concrete execution tool requirements before invoking a CLI. CLI results are normalized as ordinary executions, after which the controller evaluates task completion. Intermediate slice/checkpoint completion does not terminate autonomous execution while the user-requested completion target remains incomplete and locally actionable.",
          "alternatives": [
            {
              "option": "Keep a shared continuation manifest on every adapter",
              "rejected_because": "It leaks API protocol mechanics into CLI transports and makes successful CLI execution depend on an unrelated envelope format."
            },
            {
              "option": "Add an unconditional continue=true flag",
              "rejected_because": "It cannot distinguish target completion, user decisions, blockers, policy budgets, or locally actionable remaining work."
            },
            {
              "option": "Treat every CLI session id as a continuation token",
              "rejected_because": "Transport session identity does not encode Architect task completion or API continuation semantics."
            }
          ]
        },
        "consequences": {
          "expected": [
            "Codex and Copilot CLI executions succeed without architect_continuation fields.",
            "Standalone CLI prompts and bridge result contracts expose neutral execution requirements rather than continuation metadata.",
            "Native API continuation parsing, tokens, and controller route behavior remain available.",
            "Autonomous mode continues after intermediate checkpoints and verification when actionable requested work remains.",
            "External maintenance timeouts do not terminate unrelated locally actionable implementation."
          ],
          "risks": [
            "Text-derived task-state hints can be ambiguous until more controller-owned structured completion evidence is available.",
            "Route compatibility fields still need regression coverage so external clients keep receiving native continuation state where appropriate.",
            "Autonomous loops still depend on explicit pass/time budgets when those policies are configured."
          ]
        },
        "guard_rails": [
          "Do not require, parse, synthesize, persist, or expose Architect continuation envelopes or tokens in CLI adapter contracts.",
          "Do not classify a successful CLI execution as failed because assistant prose lacks an Architect continuation envelope.",
          "Do not treat CLI session IDs or process handles as Architect continuation tokens.",
          "Do not terminate autonomous execution solely because a slice, checkpoint, verification step, or status summary completed.",
          "Do not auto-continue when the requested target is complete, user input is genuinely required, scope must expand, a genuine external blocker exists, or an explicit policy budget requires stopping.",
          "Keep native API continuation semantics and route-boundary compatibility owned above CLI adapters."
        ],
